import { APISchemaBase, type Attribute, type Prim, type Stage } from 'typescript-usd/usd'

/**
 * This class provides API for authoring and retrieving a standard set
 * of component transformations which include a scale, a rotation, a 
 * scale-rotate pivot and a translation. The goal of the API is to enhance 
 * component-wise interchange. It achieves this by limiting the set of allowed 
 * basic ops and by specifying the order in which they are applied. In addition
 * to the basic set of ops, the 'resetXformStack' bit can also be set to 
 * indicate whether the underlying xformable resets the parent transformation 
 * (i.e. does not inherit it's parent's transformation). 
 *
 * \sa UsdGeomXformCommonAPI::GetResetXformStack()
 * \sa UsdGeomXformCommonAPI::SetResetXformStack()
 *
 * The operator-bool for the class will inform you whether an existing 
 * xformable is compatible with this API.
 *
 * The scale-rotate pivot is represented by a pair of (translate, 
 * inverse-translate) xformOps around the scale and rotate operations.
 * The rotation operation can be any of the six allowed Euler angle sets.
 * \sa UsdGeomXformOp::Type. 
 *
 * The xformOpOrder of an xformable that has all of the supported basic ops 
 * is as follows:
 * ["xformOp:translate", "xformOp:translate:pivot", "xformOp:rotateXYZ",
 * "xformOp:scale", "!invert!xformOp:translate:pivot"].
 *
 * It is worth noting that all of the ops are optional. For example, an 
 * xformable may have only a translate or a rotate. It would still be 
 * considered as compatible with this API. Individual SetTranslate(), 
 * SetRotate(), SetScale() and SetPivot() methods are provided by this API 
 * to allow such sparse authoring.
 */
export class XformCommonAPI extends APISchemaBase {
  static readonly typeName: string = "XformCommonAPI"

  static get(stage: Stage, path: string): XformCommonAPI {
    return new XformCommonAPI(stage.getPrim(path), stage)
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? []
      : []
    return names
  }

  // --(BEGIN CUSTOM CODE)--
  static readonly RotationOrderXYZ: RotationOrder = 'XYZ'
  static readonly RotationOrderXZY: RotationOrder = 'XZY'
  static readonly RotationOrderYXZ: RotationOrder = 'YXZ'
  static readonly RotationOrderYZX: RotationOrder = 'YZX'
  static readonly RotationOrderZXY: RotationOrder = 'ZXY'
  static readonly RotationOrderZYX: RotationOrder = 'ZYX'

  // OpFlags (xformCommonAPI.h:165-171) — bit flags for CreateXformOps.
  static readonly OpNone = 0
  static readonly OpTranslate = 1
  static readonly OpPivot = 2
  static readonly OpRotate = 4
  static readonly OpScale = 8

  // ---- static rotation-order conversions (xformCommonAPI.cpp:297-363) ----

  static convertRotationOrderToOpType(rotOrder: RotationOrder): XformOp.Type {
    const opType = ROT_ORDER_TO_OPTYPE[rotOrder]
    if (opType === undefined) {
      // Should never hit this.
      TF_CODING_ERROR(`Invalid rotation order <${String(rotOrder)}>.`)
      // Default rotation order is XYZ.
      return XformOp.TypeRotateXYZ
    }
    return opType
  }

  static convertOpTypeToRotationOrder(opType: XformOp.Type): RotationOrder {
    const rotOrder = OPTYPE_TO_ROT_ORDER.get(opType)
    if (rotOrder === undefined) {
      TF_CODING_ERROR(`'${XformOp.getOpTypeToken(opType)}' is not a three-axis rotate op type`)
      // Default rotation order is XYZ.
      return 'XYZ'
    }
    return rotOrder
  }

  static canConvertOpTypeToRotationOrder(opType: XformOp.Type): boolean {
    return isThreeAxisRotateOpType(opType)
  }

  // UsdGeomXformCommonAPI::GetRotationTransform (xformCommonAPI.cpp:1025-1034).
  static getRotationTransform(rotation: Vec3, rotationOrder: RotationOrder): GfMatrix4d {
    const rotateOpType = XformCommonAPI.convertRotationOrderToOpType(rotationOrder)
    return XformOp.getOpTransform(rotateOpType, [rotation[0], rotation[1], rotation[2]])
  }

  private _xformable(): Xformable {
    return new Xformable(this._prim, this._stage)
  }

  // UsdGeomXformCommonAPI::_IsCompatible (xformCommonAPI.cpp:141-154):
  // operator bool.
  isValid(): boolean {
    if (!super.isValid() || !this._prim.isValid()) return false
    const xformable = this._xformable()
    if (!xformable.isValid()) return false
    return getCommonXformOps(xformable) !== undefined
  }

  // UsdGeomXformCommonAPI::CreateXformOps (xformCommonAPI.cpp:980-1023).
  // The first argument may be a RotationOrder (used only when OpRotate is
  // requested) followed by op flags, or just op flags.
  createXformOps(...args: Array<RotationOrder | number>): Ops {
    const xformable = this._xformable()
    if (!xformable.isValid()) return emptyOps()
    let rotOrder: RotationOrder | undefined
    let flagArgs: number[]
    if (typeof args[0] === 'string') {
      rotOrder = args[0]
      flagArgs = args.slice(1) as number[]
    } else {
      flagArgs = args as number[]
    }
    const flags = flagArgs.reduce((acc, f) => acc | f, 0)
    return getOrAddCommonXformOps(
      xformable,
      rotOrder,
      Boolean(flags & XformCommonAPI.OpTranslate),
      Boolean(flags & XformCommonAPI.OpPivot),
      Boolean(flags & XformCommonAPI.OpRotate),
      Boolean(flags & XformCommonAPI.OpScale),
    )
  }

  // ---- individual setters (xformCommonAPI.cpp:923-978) ----

  setTranslate(translation: Vec3, time?: number | UsdTimeCode): boolean {
    // Can't set translate on an xformable with incompatible schema.
    const ops = this.createXformOps(XformCommonAPI.OpTranslate)
    if (!ops.translateOp.isDefined()) return false
    return ops.translateOp.set([translation[0], translation[1], translation[2]], time)
  }

  setPivot(pivot: Vec3, time?: number | UsdTimeCode): boolean {
    // Can't set pivot on an xformable with incompatible schema.
    const ops = this.createXformOps(XformCommonAPI.OpPivot)
    if (!ops.pivotOp.isDefined()) return false
    return ops.pivotOp.set([pivot[0], pivot[1], pivot[2]], time)
  }

  setRotate(
    rotation: Vec3,
    rotOrder: RotationOrder = XformCommonAPI.RotationOrderXYZ,
    time?: number | UsdTimeCode,
  ): boolean {
    // Can't set rotate on an xformable with incompatible schema.
    const ops = this.createXformOps(rotOrder, XformCommonAPI.OpRotate)
    if (!ops.rotateOp.isDefined()) return false
    return ops.rotateOp.set([rotation[0], rotation[1], rotation[2]], time)
  }

  setScale(scale: Vec3, time?: number | UsdTimeCode): boolean {
    // Can't set scale on an xformable with incompatible schema.
    const ops = this.createXformOps(XformCommonAPI.OpScale)
    if (!ops.scaleOp.isDefined()) return false
    return ops.scaleOp.set([scale[0], scale[1], scale[2]], time)
  }

  // UsdGeomXformCommonAPI::SetXformVectors (xformCommonAPI.cpp:189-212).
  setXformVectors(
    translation: Vec3,
    rotation: Vec3,
    scale: Vec3,
    pivot: Vec3,
    rotOrder: RotationOrder,
    time?: number | UsdTimeCode,
  ): boolean {
    // The call below will check rotation order compatibility before any data
    // is authored.
    const ops = this.createXformOps(
      rotOrder,
      XformCommonAPI.OpTranslate,
      XformCommonAPI.OpRotate,
      XformCommonAPI.OpScale,
      XformCommonAPI.OpPivot,
    )
    if (!ops.translateOp.isDefined() || !ops.rotateOp.isDefined()
      || !ops.scaleOp.isDefined() || !ops.pivotOp.isDefined()) {
      return false
    }
    return ops.translateOp.set([translation[0], translation[1], translation[2]], time)
      && ops.rotateOp.set([rotation[0], rotation[1], rotation[2]], time)
      && ops.scaleOp.set([scale[0], scale[1], scale[2]], time)
      && ops.pivotOp.set([pivot[0], pivot[1], pivot[2]], time)
  }

  // ---- reset-xform-stack (xformCommonAPI.cpp:675-686) ----

  getResetXformStack(): boolean {
    return this._xformable().getResetXformStack()
  }

  setResetXformStack(resetXformStack: boolean): boolean {
    return this._xformable().setResetXformStack(resetXformStack)
  }

  // ---- value retrieval ----

  // UsdGeomXformCommonAPI::GetXformVectors (xformCommonAPI.cpp:452-511).
  // Works even on incompatible xformables, in which case it does a full
  // matrix decomposition (XYZ order).
  getXformVectors(time?: number | UsdTimeCode): [Vec3, Vec3, Vec3, Vec3, RotationOrder] {
    const xformable = this._xformable()

    // Handle incompatible xform case first.
    // It's ok for an xform to be incompatible when extracting xform vectors.
    const common = getCommonXformOps(xformable)
    if (!common) {
      // We don't process (or return) resetsXformStack here. It is up to the
      // clients to call GetResetXformStack() and process it suitably.
      const localXform = xformable.getLocalTransformation(time)
      const { translation, rotation, scale } = convertMatrixToComponents(flat(localXform))
      return [translation, rotation, scale, [0, 0, 0], 'XYZ']
    }

    // If any of the ops don't exist or if no value is authored, then
    // returning identity values.
    const { t, p, r, s } = common
    const translation = opVec(t, time, [0, 0, 0])
    const rotation = opVec(r, time, [0, 0, 0])
    const scale = opVec(s, time, [1, 1, 1])
    const pivot = opVec(p, time, [0, 0, 0])
    const rotOrder: RotationOrder = r.isDefined()
      ? XformCommonAPI.convertOpTypeToRotationOrder(r.getOpType())
      : 'XYZ'
    return [translation, rotation, scale, pivot, rotOrder]
  }

  // UsdGeomXformCommonAPI::GetXformVectorsByAccumulation
  // (xformCommonAPI.cpp:513-673). For non-conforming xformOp orders, attempt
  // to reduce by accumulating common-type transforms; if irreducible, fall
  // back to full decomposition (via GetXformVectors).
  getXformVectorsByAccumulation(time?: number | UsdTimeCode): [Vec3, Vec3, Vec3, Vec3, RotationOrder] {
    // If the xformOps are compatible as authored, then just use the usual
    // component extraction method.
    if (this.isValid()) {
      return this.getXformVectors(time)
    }

    const xformOps = this._xformable().getOrderedXformOps()

    // Note that we don't currently accumulate rotate ops, so we'll be
    // looking for one xformOp of a particular rotation type. Any xformOp
    // order with multiple rotates will be considered not to conform.
    const rotateOpType = getRotateOpType(xformOps)

    const {
      commonOpTypes, translateIndex, translatePivotIndex, rotateIndex,
      translateIdentityIndex, scaleIndex, translatePivotInvertIndex,
    } = getCommonOpTypesForOpOrder(xformOps)

    // Keep a set of matrices that we'll accumulate the xformOp transforms into.
    const commonOpMatrices: Matrix4[] =
      commonOpTypes.map(() => [...IDENTITY_MATRIX] as Matrix4)

    // Scan backwards through the xformOps and list of commonOpTypes
    // accumulating transforms as we go. We scan backwards so that we
    // accumulate the inverse pivot first and can then use that to determine
    // where to split the translates at the front between pivot and non-pivot.
    let xformOpIndex = xformOps.length - 1
    let commonOpTypeIndex = commonOpTypes.length - 1

    while (xformOpIndex >= 0 && commonOpTypeIndex >= translateIndex) {
      const xformOp = xformOps[xformOpIndex]!
      const commonOpType = commonOpTypes[commonOpTypeIndex]!

      if (xformOp.getOpType() !== commonOpType) {
        commonOpTypeIndex--
        continue
      }

      // The current op has the type we expect. Multiply its transform into
      // the results.
      commonOpMatrices[commonOpTypeIndex] = mul4(
        commonOpMatrices[commonOpTypeIndex]!, flat(xformOp.getOpTransform(time)))
      xformOpIndex--

      if (commonOpType === rotateOpType) {
        // We currently do not allow rotate ops to accumulate, so as soon as
        // we match one, advance to the next commonOpType.
        commonOpTypeIndex--
      } else if (commonOpType === XformOp.TypeTranslate) {
        if (xformOp.isInverseOp()) {
          // We use the inverse-ness of translate ops to know when we should
          // move on to the next common op type.
          commonOpTypeIndex--
        } else if (
          commonOpTypeIndex === translatePivotIndex &&
          matricesAreInverses(
            commonOpMatrices[translatePivotIndex]!,
            commonOpMatrices[translatePivotInvertIndex]!,
          )
        ) {
          // We've found a pair of pivot transforms, so we'll accumulate the
          // rest of the translates into regular translation.
          commonOpTypeIndex--
        }
      }
    }

    let reducible = true
    // We didn't make it all the way through the xformOps, so there must have
    // been something in there that does not conform.
    if (xformOpIndex >= translateIndex) reducible = false
    // Make sure that any translates between the rotate and scale ops
    // accumulated to identity.
    if (translateIdentityIndex >= 0 &&
        !isMatrixIdentity(commonOpMatrices[translateIdentityIndex]!)) {
      reducible = false
    }

    // If all we saw while scanning were translates, then swap the
    // accumulated translation matrix from the "Translate (invert pivot)"
    // position into the "Translate" position.
    if (commonOpTypeIndex === translatePivotInvertIndex) {
      commonOpMatrices[translateIndex] = commonOpMatrices[commonOpTypeIndex]!
      commonOpMatrices[commonOpTypeIndex] = [...IDENTITY_MATRIX] as Matrix4
    }

    // Verify that the translate pivot and inverse translate pivot are
    // inverses of each other. If there is no pivot, these should both still
    // be identity.
    if (!matricesAreInverses(
      commonOpMatrices[translatePivotIndex]!,
      commonOpMatrices[translatePivotInvertIndex]!,
    )) {
      reducible = false
    }

    if (!reducible) {
      return this.getXformVectors(time)
    }

    const translation = extractTranslation(commonOpMatrices[translateIndex]!)
    const pivot = extractTranslation(commonOpMatrices[translatePivotIndex]!)

    let rotation: Vec3 = [0, 0, 0]
    if (rotateIndex >= 0) {
      const accumRot = extractRotation(commonOpMatrices[rotateIndex]!)
      rotation = decomposeRotation(accumRot, [1, 0, 0], [0, 1, 0], [0, 0, 1])
    }

    let scale: Vec3 = [1, 1, 1]
    if (scaleIndex >= 0) {
      const m = commonOpMatrices[scaleIndex]!
      scale = [m[0], m[5], m[10]]
    }

    const rotOrder: RotationOrder =
      XformCommonAPI.canConvertOpTypeToRotationOrder(rotateOpType)
        ? XformCommonAPI.convertOpTypeToRotationOrder(rotateOpType)
        : 'XYZ'

    return [translation, rotation, scale, pivot, rotOrder]
  }
}

// UsdGeomXformCommonAPI — a thin SRT(+pivot) facade over UsdGeomXformable.
//
// Authors and retrieves a standard, ordered set of component transforms:
//   ["xformOp:translate", "xformOp:translate:pivot", "xformOp:rotate{XYZ…}",
//    "xformOp:scale", "!invert!xformOp:translate:pivot"]
// All ops are optional; the API is "compatible" with an xformable iff its
// authored ops are a subset of this set, in this order (plus an optional
// leading "!resetXformStack!").
//
// Port of pxr/usd/usdGeom/xformCommonAPI.{h,cpp}: the ops are
// UsdGeomXformOps of the prim's UsdGeomXformable, and their transforms
// UsdGeomXformOp::GetOpTransform. Row-vector convention throughout
// (v' = v·M); op composition matches GfMatrix4d's row-vector operator*
// (left = more local).

import { TF_CODING_ERROR, RaiseWarning as TF_WARN } from 'typescript-usd/tf'
import type { TimeCode as UsdTimeCode } from 'typescript-usd/usd'
import {
  type Matrix4,
  type Vec3,
  IDENTITY_MATRIX,
  Matrix4d as GfMatrix4d,
  mul4,
  factorMatrix,
  extractRotation,
  decomposeRotation,
  orthonormalizeMatrix,
} from 'typescript-usd/gf'
import { XformOp } from './xformOp.ts'
import { Xformable } from './xformable.ts'
import { asVec3, plain } from './valueUtils.ts'

// ---- RotationOrder enum (UsdGeomXformCommonAPI::RotationOrder) ----

export type RotationOrder = 'XYZ' | 'XZY' | 'YXZ' | 'YZX' | 'ZXY' | 'ZYX'

// Return type for CreateXformOps() (UsdGeomXformCommonAPI::Ops,
// xformCommonAPI.h:177-183). An op that is absent or could not be created
// is an XformOp that is not defined (isDefined() false).
export interface Ops {
  translateOp: XformOp
  pivotOp: XformOp
  rotateOp: XformOp
  scaleOp: XformOp
  inversePivotOp: XformOp
}

function emptyOps(): Ops {
  return {
    translateOp: new XformOp(), pivotOp: new XformOp(), rotateOp: new XformOp(),
    scaleOp: new XformOp(), inversePivotOp: new XformOp(),
  }
}

// ---- op-type classification (xformCommonAPI.cpp:239-283) ----

function isThreeAxisRotateOpType(opType: XformOp.Type): boolean {
  return opType >= XformOp.TypeRotateXYZ && opType <= XformOp.TypeRotateZYX
}
function isRotateOpType(opType: XformOp.Type): boolean {
  return opType >= XformOp.TypeRotateX && opType <= XformOp.TypeRotateZYX
}

const ROT_ORDER_TO_OPTYPE: Record<RotationOrder, XformOp.Type> = {
  XYZ: XformOp.TypeRotateXYZ, XZY: XformOp.TypeRotateXZY, YXZ: XformOp.TypeRotateYXZ,
  YZX: XformOp.TypeRotateYZX, ZXY: XformOp.TypeRotateZXY, ZYX: XformOp.TypeRotateZYX,
}
const OPTYPE_TO_ROT_ORDER = new Map<XformOp.Type, RotationOrder>(
  Object.entries(ROT_ORDER_TO_OPTYPE).map(([order, opType]) => [opType, order as RotationOrder]))

// _GetRotateOpType (xformCommonAPI.cpp:284-294).
function getRotateOpType(ops: readonly XformOp[]): XformOp.Type {
  for (const op of ops) {
    if (isRotateOpType(op.getOpType())) return op.getOpType()
  }
  return XformOp.TypeRotateXYZ
}

// _GetCommonOpTypesForOpOrder (xformCommonAPI.cpp:364-434): the common op
// types the xformOps could be reduced to by accumulation, with named
// indices into them (-1 when absent).
function getCommonOpTypesForOpOrder(xformOps: readonly XformOp[]): {
  commonOpTypes: XformOp.Type[]
  translateIndex: number, translatePivotIndex: number, rotateIndex: number
  translateIdentityIndex: number, scaleIndex: number, translatePivotInvertIndex: number
} {
  let hasRotateOp = false
  let hasScaleOp = false
  let numInverseTranslateOps = 0
  for (const op of xformOps) {
    const opType = op.getOpType()
    if (isRotateOpType(opType)) hasRotateOp = true
    else if (opType === XformOp.TypeScale) hasScaleOp = true
    else if (opType === XformOp.TypeTranslate && op.isInverseOp()) numInverseTranslateOps++
  }

  const commonOpTypes: XformOp.Type[] = []
  let currentIndex = 0
  commonOpTypes.push(XformOp.TypeTranslate)
  const translateIndex = currentIndex++
  commonOpTypes.push(XformOp.TypeTranslate)
  const translatePivotIndex = currentIndex++
  let rotateIndex = -1
  let translateIdentityIndex = -1
  let scaleIndex = -1
  if (hasRotateOp) {
    commonOpTypes.push(getRotateOpType(xformOps))
    rotateIndex = currentIndex++
  }
  if (numInverseTranslateOps > 1) {
    // If more than one inverse translate is present, assume that means that
    // both a rotate pivot and a scale pivot are specified. For it to be
    // reducible, they must be at the same location in space, in which case
    // they'll accumulate to identity in the translateIdentityIndex position.
    commonOpTypes.push(XformOp.TypeTranslate)
    translateIdentityIndex = currentIndex++
  }
  if (hasScaleOp) {
    commonOpTypes.push(XformOp.TypeScale)
    scaleIndex = currentIndex++
  }
  commonOpTypes.push(XformOp.TypeTranslate)
  const translatePivotInvertIndex = currentIndex++
  return {
    commonOpTypes, translateIndex, translatePivotIndex, rotateIndex,
    translateIdentityIndex, scaleIndex, translatePivotInvertIndex,
  }
}

// The common op names of _GetCommonXformOps (xformCommonAPI.cpp:720-727).
const TRANSLATE_NAME = XformOp.getOpName(XformOp.TypeTranslate)
const PIVOT_NAME = XformOp.getOpName(XformOp.TypeTranslate, 'pivot')
const SCALE_NAME = XformOp.getOpName(XformOp.TypeScale)

interface CommonXformOps {
  t: XformOp, p: XformOp, r: XformOp, s: XformOp, pInv: XformOp, resetXformStack: boolean
}

// _GetCommonXformOps (xformCommonAPI.cpp:687-823): the XformCommonAPI
// component ops of xformable (an op not defined where absent), or
// undefined when its ops are not in a compatible order.
function getCommonXformOps(xformable: Xformable): CommonXformOps | undefined {
  const tempResetXformStack = { value: false }
  const xformOps = xformable.getOrderedXformOps(tempResetXformStack)
  if (xformOps.length > 5) return undefined

  // Search one-by-one for the ops in the correct order. We can skip ops in
  // the "expected" order (that is, all the common ops are optional) but we
  // can't skip ops in the "actual" order (that is, extra ops aren't
  // allowed).
  let it = 0
  const at = (name: string, inverse: boolean): boolean =>
    it < xformOps.length && xformOps[it]!.getName() === name && xformOps[it]!.isInverseOp() === inverse
  let t = new XformOp()
  if (at(TRANSLATE_NAME, false)) t = xformOps[it++]!
  let p = new XformOp()
  if (at(PIVOT_NAME, false)) p = xformOps[it++]!
  let r = new XformOp()
  if (it < xformOps.length
      && XformCommonAPI.canConvertOpTypeToRotationOrder(xformOps[it]!.getOpType())
      && !xformOps[it]!.isInverseOp()) {
    r = xformOps[it++]!
  }
  let s = new XformOp()
  if (at(SCALE_NAME, false)) s = xformOps[it++]!
  let pInv = new XformOp()
  if (at(PIVOT_NAME, true)) pInv = xformOps[it++]!

  // If we did not reach the end of the xformOps vector, then there were
  // extra ops that did not match any of the expected ops.
  if (it !== xformOps.length) return undefined

  // Verify that translate pivot and inverse translate pivot are either both
  // present or both absent.
  if (p.isDefined() !== pInv.isDefined()) return undefined

  return { t, p, r, s, pInv, resetXformStack: tempResetXformStack.value }
}

// _GetOrAddCommonXformOps (xformCommonAPI.cpp:825-921): like
// getCommonXformOps, also adding each requested op that does not yet exist.
// When creating a rotate op, rotOrder chooses its type (or validates the
// existing one's); without one, a rotateXYZ op is created (or any existing
// three-axis rotate returned).
function getOrAddCommonXformOps(
  xformable: Xformable,
  rotOrder: RotationOrder | undefined,
  createTranslate: boolean,
  createPivot: boolean,
  createRotate: boolean,
  createScale: boolean,
): Ops {
  // Can't get or add ops on an xformable with incompatible schema.
  const common = getCommonXformOps(xformable)
  if (!common) {
    TF_WARN(`Could not determine xform ops for incompatible xformable <${xformable.path}>`)
    return emptyOps()
  }
  let { t, p, r, s, pInv } = common
  const { resetXformStack } = common

  // If creating the rotate op and the rotate op already exists, we must check
  // that the existing rotation order matches the requested rotation order.
  // We do this first so that we can early-exit without modifying the xform
  // op order if we encounter an error.
  if (createRotate && rotOrder !== undefined && r.isDefined()) {
    const existingRotOrder = XformCommonAPI.convertOpTypeToRotationOrder(r.getOpType())
    if (existingRotOrder !== rotOrder) {
      TF_CODING_ERROR(`Rotation order mismatch on prim <${xformable.path}> `
        + `(RotationOrder${rotOrder} != RotationOrder${existingRotOrder})`)
      return emptyOps()
    }
  }

  // Add ops if they were requested but the ops do not yet exist.
  let addedOps = false
  if (createTranslate && !t.isDefined()) {
    addedOps = true
    t = xformable.addTranslateOp()
    if (!t.isDefined()) return emptyOps()
  }
  if (createPivot && !p.isDefined()) {
    addedOps = true
    p = xformable.addTranslateOp(XformOp.PrecisionFloat, 'pivot')
    pInv = xformable.addTranslateOp(XformOp.PrecisionFloat, 'pivot', /* isInverseOp */ true)
    if (!p.isDefined() || !pInv.isDefined()) return emptyOps()
  }
  if (createRotate && !r.isDefined()) {
    addedOps = true
    const rotateOpType = rotOrder !== undefined
      ? XformCommonAPI.convertRotationOrderToOpType(rotOrder)
      : XformOp.TypeRotateXYZ
    r = xformable.addXformOp(rotateOpType, XformOp.PrecisionFloat)
    if (!r.isDefined()) return emptyOps()
  }
  if (createScale && !s.isDefined()) {
    addedOps = true
    s = xformable.addScaleOp()
    if (!s.isDefined()) return emptyOps()
  }

  // Only update the xform op order if we had to add new ops.
  if (addedOps) {
    const newXformOps = [t, p, r, s, pInv].filter(op => op.isDefined())
    xformable.setXformOpOrder(newXformOps, resetXformStack)
  }

  return { translateOp: t, pivotOp: p, rotateOp: r, scaleOp: s, inversePivotOp: pInv }
}

// An op's vector value at time, or the fallback when the op is not defined
// or has no value (GetXformVectors and _GetFromVec3dOrVec3f,
// xformCommonAPI.cpp:436-450, 483-501).
function opVec(op: XformOp, time: number | UsdTimeCode | undefined, fallback: Vec3): Vec3 {
  if (!op.isDefined()) return [...fallback] as Vec3
  const v = op.get(time)
  if (Array.isArray(plain(v))) return asVec3(v)
  return [...fallback] as Vec3
}

// ---- Matrix helpers (GfMatrix4d fragment used by the accumulation path) ----

// A GfMatrix4d as the row-major Matrix4 the gf helpers take.
function flat(m: GfMatrix4d): Matrix4 {
  return [...m.GetArray()] as Matrix4
}

function extractTranslation(m: Matrix4): Vec3 {
  return [m[12], m[13], m[14]]
}

// _IsMatrixIdentity (xformCommonAPI.cpp:213-229): GfIsClose on each row,
// tolerance 1e-6.
function isMatrixIdentity(m: Matrix4): boolean {
  const tol2 = 1e-6 * 1e-6
  const id = IDENTITY_MATRIX
  for (let r = 0; r < 4; r++) {
    let s = 0
    for (let c = 0; c < 4; c++) {
      const d = m[r * 4 + c]! - id[r * 4 + c]!
      s += d * d
    }
    if (s > tol2) return false
  }
  return true
}

// _MatricesAreInverses (xformCommonAPI.cpp:231-236).
function matricesAreInverses(m1: Matrix4, m2: Matrix4): boolean {
  return isMatrixIdentity(mul4(m1, m2))
}

// _ConvertMatrixToComponents (xformCommonAPI.cpp:169-187): GfMatrix4d::
// Factor into component vectors, XYZ rotation order.
function convertMatrixToComponents(matrix: Matrix4): {
  translation: Vec3; rotation: Vec3; scale: Vec3
} {
  const f = factorMatrix(matrix)
  const scale: Vec3 = [f.scale[0], f.scale[1], f.scale[2]]
  // Factor's `u` (the rotation, possibly with shear) is our f.shear.
  const rotMat = orthonormalizeMatrix(f.shear)
  const rot = extractRotation(rotMat)
  // _RotMatToRotXYZ: Decompose(Z, Y, X) then (angles[2], angles[1], angles[0]).
  const angles = decomposeRotation(rot, [0, 0, 1], [0, 1, 0], [1, 0, 0])
  const rotation: Vec3 = [angles[2], angles[1], angles[0]]
  return { translation: [f.translation[0], f.translation[1], f.translation[2]], rotation, scale }
}
